import {icon} from './dashboard.mjs';
import {FUNDING_ASSETS,networkLabel} from './funding-catalog.mjs';
export const CURRENCIES=FUNDING_ASSETS;
export const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const usd=cents=>'$'+(cents/100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
export function currencyFields(prefix,currency='BTC',network,routes=null){const c=CURRENCIES[currency];return '<div class="transfer-field"><label for="'+prefix+'-currency">Cryptocurrency</label><div class="currency-select">'+(c.icon?'<img src="/assets/'+c.icon+'@2x.png" alt="">':'<span class="tether-mark" aria-hidden="true">'+c.mark+'</span>')+'<select id="'+prefix+'-currency">'+Object.entries(CURRENCIES).map(([s,a])=>'<option value="'+s+'" '+(s===currency?'selected':'')+'>'+s+' · '+a.name+'</option>').join('')+'</select></div></div><div class="transfer-field"><label for="'+prefix+'-network">Network</label><select id="'+prefix+'-network">'+c.networks.map(n=>'<option value="'+n+'" '+(n===network?'selected':'')+'>'+networkLabel(currency,n)+(routes?(routes.find(r=>r.asset===currency&&r.network===n)?.enabled?'':routes.find(r=>r.asset===currency&&r.network===n)?.address?' · Awaiting activation':' · Unavailable'):'')+'</option>').join('')+'</select></div>';}
export function historyHTML(type){return '<section class="deposit-panel deposit-history"><h2>'+icon(type)+' '+(type==='withdraw'?'Withdrawal':'Deposit')+' History</h2><div id="funding-history"><div class="deposit-history-empty">'+icon(type)+'<p>No '+(type==='withdraw'?'withdrawal':'deposit')+' history</p></div></div></section>';}
export function renderHistory(slot,rows,{open,cancel}={}){slot.replaceChildren();if(!rows.length){slot.innerHTML='<div class="deposit-history-empty"><p>No transactions yet</p></div>';return;}for(const row of rows){const card=document.createElement('article');card.className='funding-history-row';card.innerHTML='<div><strong>'+escapeHTML(row.amount)+' '+row.asset+'</strong><span class="funding-status">'+escapeHTML(row.status.replaceAll('_',' '))+'</span></div><p>'+escapeHTML(networkLabel(row.asset,row.network))+' · '+new Date(row.created_at).toLocaleDateString()+'</p><small>'+escapeHTML(row.payout_hash||row.transaction_hash||row.id)+'</small>';if(row.kind==='withdrawal'){const p=document.createElement('p');p.textContent='Destination: '+row.address+(row.memo?' · Memo: '+row.memo:'')+(row.review_note?' · Review: '+row.review_note:'')+(row.status==='processing'?' · An administrator is processing this payment.':'');card.append(p);}if(open){const b=document.createElement('button');b.className='transfer-back';b.textContent='View deposit';b.onclick=()=>open(row);card.append(b);}if(cancel&&(row.status==='held'||(row.kind==='withdrawal'&&row.status==='pending_review'))){const b=document.createElement('button');b.className='transfer-back';b.textContent='Cancel request & restore balance';b.onclick=()=>cancel(row,b);card.append(b);}slot.append(card);}}
